INSERT INTO [KhoaHoc] ([MaKhoaHoc], [TenKhoaHoc], [NgoaiNgu], [CapDo], [HocPhi], [SoBuoi], [MoTa], [TrangThai]) VALUES
(1, N'IELTS Intensive Mục Tiêu 6.5 - 7.5+', N'Tiếng Anh', N'Cao cấp (C1/C2)', 6500000.00, 36, N'Khóa học luyện thi IELTS chuyên sâu 4 kỹ năng Nghe - Nói - Đọc - Viết với giảng viên 8.5 IELTS và chấm bài trực tiếp.', N'Đang mở'),
(2, N'Tiếng Anh Giao Tiếp Quốc Tế Phản Xạ Nhanh', N'Tiếng Anh', N'Trung cấp (B1/B2)', 3800000.00, 24, N'Rèn luyện kỹ năng phát âm chuẩn IPA, tăng vốn từ vựng thực tế và phản xạ giao tiếp tự tin trong môi trường làm việc toàn cầu.', N'Đang mở'),
(3, N'Tiếng Hàn Giao Tiếp & Luyện Thi TOPIK II', N'Tiếng Hàn', N'Trung cấp (B1/B2)', 4200000.00, 30, N'Trang bị ngữ pháp trung cấp và chiến thuật giải đề thi TOPIK cấp 3-4, nâng cao kỹ năng đàm thoại phong cách chuẩn Hàn.', N'Đang mở'),
(4, N'Tiếng Hàn Nhập Môn Cho Người Mới Bắt Đầu', N'Tiếng Hàn', N'Sơ cấp (A1/A2)', 2500000.00, 20, N'Bảng chữ cái Hangeul, cách ghép âm, từ vựng cơ bản và các mẫu câu giao tiếp đời sống hàng ngày dễ hiểu.', N'Đang mở'),
(5, N'Tiếng Nhật Cấp Tốc JLPT N3', N'Tiếng Nhật', N'Trung cấp (B1/B2)', 4800000.00, 32, N'Khóa học tổng hợp Kanji, Ngữ pháp, Đọc hiểu và Nghe hiểu theo chuẩn cấu trúc đề thi JLPT N3 thực tế.', N'Đang mở'),
(6, N'Tiếng Trung Toàn Diện HSK 3 - HSK 4', N'Tiếng Trung', N'Trung cấp (B1/B2)', 4500000.00, 30, N'Phát triển toàn diện từ vựng, ngữ pháp và khẩu ngữ tiếng Trung thương mại, cam kết đầu ra chứng chỉ HSK 3/4.', N'Đang mở'),
(1002, N'Ôn mất gốc Tiếng Anh', N'Tiếng Anh', N'Sơ cấp (A1/A2)', 3000000.00, 24, N'Đối với những người chưa có kỹ năng tiếng anh', N'Đang mở'),
(1003, N'Tiếng Anh Giao Tiếp Cơ Bản', N'Tiếng Anh', N'Sơ cấp (A1/A2)', 2500000.00, 30, N'Khóa học tiếng Anh giao tiếp chuẩn quốc tế cho người mới bắt đầu, rèn luyện phát âm và phản xạ tự nhiên.', N'Đang mở'),
(1004, N'Tiếng Anh Giao Tiếp Nâng Cao', N'Tiếng Anh', N'Trung cấp (B1/B2)', 3500000.00, 40, N'Nâng cao phản xạ giao tiếp tự tin, thuyết trình và đàm phán trong môi trường học tập & làm việc quốc tế.', N'Đang mở'),
(1005, N'Luyện Thi IELTS 6.0+', N'Tiếng Anh', N'IELTS', 5500000.00, 60, N'Luyện thi chuyên sâu 4 kỹ năng Nghe - Nói - Đọc - Viết, cam kết đầu ra IELTS 6.0+.', N'Đang mở'),
(1006, N'Luyện Thi IELTS 7.0+', N'Tiếng Anh', N'IELTS', 7000000.00, 80, N'Khóa luyện thi IELTS học thuật nâng cao, chiến thuật làm bài chinh phục band điểm 7.0 - 8.0+.', N'Đang mở'),
(1007, N'Tiếng Anh Học Thuật TOEFL', N'Tiếng Anh', N'TOEFL', 6000000.00, 60, N'Chuẩn bị toàn diện cho kỳ thi TOEFL iBT quốc tế phục vụ săn học bổng và du học.', N'Đang mở'),
(1008, N'Tiếng Anh Thương Mại Quốc Tế', N'Tiếng Anh', N'Trung cấp (B1/B2)', 4500000.00, 45, N'Kỹ năng viết email chuyên nghiệp, thuyết trình kinh doanh và giao dịch thương mại bằng tiếng Anh.', N'Đang mở'),
(1009, N'Tiếng Nhật Sơ Cấp JLPT N5', N'Tiếng Nhật', N'N5', 3000000.00, 36, N'Nhập môn tiếng Nhật từ bảng chữ cái Hiragana/Katakana đến Kanji cơ bản, cam kết thi đỗ JLPT N5.', N'Đang mở'),
(1010, N'Tiếng Nhật Trung Cấp JLPT N4', N'Tiếng Nhật', N'N4', 3500000.00, 40, N'Mở rộng vốn từ vựng, ngữ pháp ứng dụng và luyện thi chắc chắn chứng chỉ JLPT N4.', N'Đang mở'),
(1011, N'Tiếng Nhật Cao Cấp JLPT N3', N'Tiếng Nhật', N'N3', 4500000.00, 50, N'Giao tiếp tiếng Nhật lưu loát trong công việc, luyện thi cấp tốc đạt JLPT N3.', N'Đang mở'),
(1012, N'Tiếng Nhật Thương Mại JLPT N2', N'Tiếng Nhật', N'N2', 6000000.00, 70, N'Khóa tiếng Nhật chuyên nghiệp cho doanh nghiệp Nhật Bản và luyện thi JLPT N2.', N'Đang mở'),
(1013, N'Tiếng Hàn Cơ Bản TOPIK I', N'Tiếng Hàn', N'TOPIK I', 2800000.00, 32, N'Học tiếng Hàn từ bảng chữ cái Hangeul, giao tiếp đời sống và thi đỗ chứng chỉ TOPIK I.', N'Đang mở'),
(1014, N'Tiếng Hàn Trung Cấp TOPIK II', N'Tiếng Hàn', N'TOPIK II', 4000000.00, 48, N'Nâng cao ngữ pháp, đọc hiểu và kỹ năng viết luận thi TOPIK II cấp độ 3 - 4.', N'Đang mở'),
(1015, N'Tiếng Hàn Du Học & Định Cư', N'Tiếng Hàn', N'Cao cấp (C1/C2)', 5500000.00, 60, N'Chương trình chuyên biệt cho học viên chuẩn bị du học đại học và làm việc tại Hàn Quốc.', N'Đang mở'),
(1016, N'Tiếng Trung Cơ Bản HSK 1 - 2', N'Tiếng Trung', N'HSK 1-2', 2500000.00, 30, N'Nhập môn phát âm Pinyin, quy tắc viết chữ Hán và giao tiếp cơ bản, đạt HSK 1-2.', N'Đang mở'),
(1017, N'Tiếng Trung Giao Tiếp HSK 3', N'Tiếng Trung', N'HSK 3', 3500000.00, 42, N'Rèn luyện khẩu ngữ giao tiếp thực tế và luyện đề thi chứng chỉ quốc tế HSK 3.', N'Đang mở'),
(1018, N'Tiếng Trung Thương Mại HSK 4', N'Tiếng Trung', N'HSK 4', 4800000.00, 56, N'Tiếng Trung thương mại, đàm phán hợp đồng, xuất nhập khẩu và luyện thi HSK 4.', N'Đang mở'),
(1019, N'Tiếng Trung Nâng Cao HSK 5', N'Tiếng Trung', N'HSK 5', 6000000.00, 70, N'Khóa chuyên sâu từ vựng cao cấp, đọc báo chí và chinh phục chứng chỉ HSK 5.', N'Đang mở'),
(1020, N'Tiếng Pháp Nhập Môn DELF A1 - A2', N'Tiếng Pháp', N'A1-A2', 3000000.00, 36, N'Khám phá ngôn ngữ Pháp lãng mạn, phát âm chuẩn Paris và đạt DELF A1 - A2.', N'Đang mở'),
(1021, N'Tiếng Pháp Giao Tiếp DELF B1', N'Tiếng Pháp', N'B1', 4200000.00, 48, N'Giao tiếp tiếng Pháp tự nhiên, phản xạ linh hoạt và luyện thi chứng chỉ DELF B1.', N'Đang mở'),
(1022, N'Tiếng Pháp Nâng Cao DALF C1', N'Tiếng Pháp', N'B2-C1', 6500000.00, 72, N'Khóa học học thuật chuyên sâu phục vụ du học Pháp và định cư các nước Pháp ngữ.', N'Đang mở'),
(1023, N'Tiếng Anh Thiếu Nhi (6 - 10 Tuổi)', N'Tiếng Anh', N'Thiếu nhi', 2000000.00, 24, N'Phương pháp học tiếng Anh qua bài hát, trò chơi tương tác sinh động giúp trẻ yêu thích ngôn ngữ.', N'Đang mở'),
(1024, N'Tiếng Anh Thiếu Niên (10 - 14 Tuổi)', N'Tiếng Anh', N'Thiếu nhi', 2200000.00, 28, N'Củng cố ngữ pháp nền tảng, mở rộng vốn từ vựng và tự tin giao tiếp tiếng Anh.', N'Đang mở'),
(1025, N'Tiếng Nhật Hội Thoại & Văn Hóa', N'Tiếng Nhật', N'Sơ cấp (A1/A2)', 2800000.00, 30, N'Khóa học đàm thoại thực tế khi du lịch, làm việc và tìm hiểu văn hóa đất nước mặt trời mọc.', N'Đang mở'),
