INSERT INTO [BinhLuan] ([MaBinhLuan], [NoiDung], [NgayBinhLuan], [MaTaiKhoan], [MaKhoaHoc], [MaBaiViet]) VALUES
(1, N'Khóa học này lộ trình rất rõ ràng và bài bản, em học thử buổi đầu thấy thầy cô phát âm cực chuẩn ạ!', '2026-10-13 13:56:42.784', 2, 1, NULL),
(2, N'Chào bạn, trung tâm luôn hỗ trợ tài liệu độc quyền và bài thi thử mock-test miễn phí hàng tuần nhé!', '2026-10-13 15:56:42.784', 1, 1, NULL),
(3, N'Lớp học buổi tối có còn suất không ạ? Mình muốn đăng ký theo nhóm 2 người để nhận ưu đãi.', '2026-10-13 21:56:42.784', 3, 2, NULL),
(4, N'Giáo trình rất sát với format đề thi thật. Mình vừa thi đạt mục tiêu tháng trước, cảm ơn trung tâm nhiều!', '2026-10-14 01:56:42.784', 4, 1, NULL),
(5, N'Phòng học hiện đại, có điều hòa và máy chiếu xịn xò lắm các bạn ơi.', '2026-10-14 05:56:42.784', 2, 2, NULL),
(6, N'Có chính sách chia đợt đóng học phí không ạ?', '2026-10-14 07:11:42.784', 5, 3, NULL),
(7, N'Khóa học IELTS này có lớp cấp tốc cuối tuần không ad?', '2026-10-14 07:58:01.470', 2, 1, NULL),
(10, N'hhh', '2026-10-14 08:03:33.555', 1, 1, NULL),
(11, N'Tuyệt vời quá ạ! Em rất háo hức chờ buổi học đầu tiên tuần này 🎉📚', '2026-10-14 13:10:41.960', 3, NULL, 1),
